import{_ as n,o as a,c as t,e as p}from"./app-6c9584fa.js";const e={};function o(l,s){return a(),t("div",null,[...s[0]||(s[0]=[p(`<h1 id="_6-1-从单体-agent-到多智能体架构-multi-agent-system" tabindex="-1"><a class="header-anchor" href="#_6-1-从单体-agent-到多智能体架构-multi-agent-system" aria-hidden="true">#</a> 6.1 从单体 Agent 到多智能体架构 (Multi-Agent System)</h1><p>本节目标：把当前 Demo 级别的“单体 Agent + 一次性 Prompt”演进为可扩展、可观测、可并行的多智能体协作系统，并且能在现有 NestJS + BullMQ + Redis + WebSocket/SSE 的技术栈里自然落地。</p><hr><h2 id="_6-1-1-现状回顾-单体-agent-的上限在哪里" tabindex="-1"><a class="header-anchor" href="#_6-1-1-现状回顾-单体-agent-的上限在哪里" aria-hidden="true">#</a> 6.1.1 现状回顾：单体 Agent 的上限在哪里</h2><p>以 <code>ai-data-analyzer</code> 为例，目前后端的分析入口集中在一个服务中完成（如 <code>AnalysisService</code> 的 <code>analyzeData</code> / <code>analyzeText</code> 一类方法）。这类单体设计的优势是简单、能快速跑通流程，但随着需求增长，会出现典型瓶颈：</p><ul><li>上下文过载：数据、用户意图、工具调用、图表配置、解释文本全部塞进一次上下文，Token 成本和混乱度快速上升</li><li>角色混杂：同一个 Agent 既要“规划任务”，又要“写处理逻辑”，还要“校验结果”，很难稳定</li><li>可观测性不足：很难回答“这一步为什么这么做”“在哪里失败”“重试了几次”“哪一次输出被采用”</li><li>可复用性差：某些能力（清洗、聚合、图表、解释、异常检测）很难拆成可组合模块</li><li>并行做不到：例如“同时生成 3 个图表 + 同时做质量诊断”在单体里只能串行</li></ul><p>因此，第一个真正从 Demo 走向工程化的改造点，就是把“一个大脑”拆成“多个可控的脑区”，并明确它们之间的协议。</p><hr><h2 id="_6-1-2-架构目标-supervisor-worker-明确协议-强可观测" tabindex="-1"><a class="header-anchor" href="#_6-1-2-架构目标-supervisor-worker-明确协议-强可观测" aria-hidden="true">#</a> 6.1.2 架构目标：Supervisor/Worker + 明确协议 + 强可观测</h2><p>推荐采用 <strong>Supervisor-Worker（主管理者 + 工作者）</strong> 的经典模式：</p><ul><li>Supervisor（主管理者）：负责理解用户意图、拆解任务、调度 Worker、合并产出、兜底重试</li><li>Workers（专业工人）：每个 Worker 只做一类事，并以结构化产出为边界</li></ul><p>为了让系统“稳定而可扩展”，要给多智能体系统加三条工程约束：</p><ol><li>所有 Agent 之间交互必须走结构化协议（JSON Schema / Zod），禁止“自由发挥传话”</li><li>所有中间步骤都可追踪（可存储/可回放/可重试），而不是只存最终文本</li><li>每个 Worker 都有明确输入输出、失败语义、超时策略、最大步数</li></ol><hr><h2 id="_6-1-3-角色拆分-最小可用的-4-agent-编制" tabindex="-1"><a class="header-anchor" href="#_6-1-3-角色拆分-最小可用的-4-agent-编制" aria-hidden="true">#</a> 6.1.3 角色拆分：最小可用的 4 Agent 编制</h2><p>从“能落地”出发，第一版就拆到 4 个角色即可（多了会先把工程复杂度拉爆）：</p><h3 id="a-router-agent-路由与拆解" tabindex="-1"><a class="header-anchor" href="#a-router-agent-路由与拆解" aria-hidden="true">#</a> A. Router Agent（路由与拆解）</h3><p>职责：</p><ul><li>从用户输入中提取：目标（Goal）、数据范围（Scope）、输出形态（Text / Charts / Tables）、约束（时序/维度/单位）</li><li>生成一个结构化的任务计划（Plan），每一步明确交给哪个 Worker</li><li>识别风险与缺失信息（列名不一致、单位不明确、时间格式异常）并生成澄清问题（可选）</li></ul><p>输出（示例）：</p><div class="language-json line-numbers-mode" data-ext="json"><pre class="language-json"><code><span class="token punctuation">{</span>
  <span class="token property">&quot;goal&quot;</span><span class="token operator">:</span> <span class="token string">&quot;分析销售趋势并找出异常月份&quot;</span><span class="token punctuation">,</span>
  <span class="token property">&quot;tasks&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span>
    <span class="token punctuation">{</span> <span class="token property">&quot;id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;t1&quot;</span><span class="token punctuation">,</span> <span class="token property">&quot;type&quot;</span><span class="token operator">:</span> <span class="token string">&quot;data_profile&quot;</span><span class="token punctuation">,</span> <span class="token property">&quot;inputs&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token property">&quot;focus&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token string">&quot;date&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;amount&quot;</span><span class="token punctuation">]</span> <span class="token punctuation">}</span> <span class="token punctuation">}</span><span class="token punctuation">,</span>
    <span class="token punctuation">{</span> <span class="token property">&quot;id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;t2&quot;</span><span class="token punctuation">,</span> <span class="token property">&quot;type&quot;</span><span class="token operator">:</span> <span class="token string">&quot;compute_metrics&quot;</span><span class="token punctuation">,</span> <span class="token property">&quot;inputs&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token property">&quot;metrics&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token string">&quot;MoM&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;YoY&quot;</span><span class="token punctuation">]</span> <span class="token punctuation">}</span> <span class="token punctuation">}</span><span class="token punctuation">,</span>
    <span class="token punctuation">{</span> <span class="token property">&quot;id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;t3&quot;</span><span class="token punctuation">,</span> <span class="token property">&quot;type&quot;</span><span class="token operator">:</span> <span class="token string">&quot;chart_spec&quot;</span><span class="token punctuation">,</span> <span class="token property">&quot;inputs&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token property">&quot;charts&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token string">&quot;line_sales&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;bar_growth&quot;</span><span class="token punctuation">]</span> <span class="token punctuation">}</span> <span class="token punctuation">}</span><span class="token punctuation">,</span>
    <span class="token punctuation">{</span> <span class="token property">&quot;id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;t4&quot;</span><span class="token punctuation">,</span> <span class="token property">&quot;type&quot;</span><span class="token operator">:</span> <span class="token string">&quot;review&quot;</span><span class="token punctuation">,</span> <span class="token property">&quot;inputs&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token property">&quot;checks&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token string">&quot;unit&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;outlier&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;chart_consistency&quot;</span><span class="token punctuation">]</span> <span class="token punctuation">}</span> <span class="token punctuation">}</span><span class="token punctuation">,</span>
    <span class="token punctuation">{</span> <span class="token property">&quot;id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;t5&quot;</span><span class="token punctuation">,</span> <span class="token property">&quot;type&quot;</span><span class="token operator">:</span> <span class="token string">&quot;final_report&quot;</span><span class="token punctuation">,</span> <span class="token property">&quot;inputs&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token property">&quot;style&quot;</span><span class="token operator">:</span> <span class="token string">&quot;bullet&quot;</span><span class="token punctuation">,</span> <span class="token property">&quot;audience&quot;</span><span class="token operator">:</span> <span class="token string">&quot;business&quot;</span> <span class="token punctuation">}</span> <span class="token punctuation">}</span>
  <span class="token punctuation">]</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="b-data-coder-agent-数据处理-计算" tabindex="-1"><a class="header-anchor" href="#b-data-coder-agent-数据处理-计算" aria-hidden="true">#</a> B. Data Coder Agent（数据处理/计算）</h3><p>职责：</p><ul><li>把任务转成可执行的计算（优先工具调用，其次代码执行器，最后才是“口算”）</li><li>输出结构化结果：指标表、分组统计、异常点列表、字段映射等</li></ul><p>注意：</p><ul><li>第一版不需要真的“写 TypeScript 代码并跑”，先做到“输出结构化计算结果 + 可复核的计算过程”即可</li><li>到 6.2 章再把它升级为“写 Python/SQL 并执行”</li></ul><h3 id="c-viz-agent-图表编排" tabindex="-1"><a class="header-anchor" href="#c-viz-agent-图表编排" aria-hidden="true">#</a> C. Viz Agent（图表编排）</h3><p>职责：</p><ul><li>根据 Data Coder 的结构化结果，生成前端可消费的图表配置（例如 ECharts option）</li><li>强制要求图表来源数据可追溯（引用 resultKey / 数据表名 / 字段名）</li></ul><p>输出（示例）：</p><div class="language-json line-numbers-mode" data-ext="json"><pre class="language-json"><code><span class="token punctuation">{</span>
  <span class="token property">&quot;charts&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span>
    <span class="token punctuation">{</span>
      <span class="token property">&quot;id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;line_sales&quot;</span><span class="token punctuation">,</span>
      <span class="token property">&quot;library&quot;</span><span class="token operator">:</span> <span class="token string">&quot;echarts&quot;</span><span class="token punctuation">,</span>
      <span class="token property">&quot;option&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token property">&quot;xAxis&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token property">&quot;type&quot;</span><span class="token operator">:</span> <span class="token string">&quot;category&quot;</span> <span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token property">&quot;yAxis&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token property">&quot;series&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token punctuation">{</span> <span class="token property">&quot;type&quot;</span><span class="token operator">:</span> <span class="token string">&quot;line&quot;</span> <span class="token punctuation">}</span><span class="token punctuation">]</span> <span class="token punctuation">}</span><span class="token punctuation">,</span>
      <span class="token property">&quot;dataRef&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token property">&quot;resultKey&quot;</span><span class="token operator">:</span> <span class="token string">&quot;monthly_sales_table&quot;</span> <span class="token punctuation">}</span>
    <span class="token punctuation">}</span>
  <span class="token punctuation">]</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="d-reviewer-agent-审阅与守门" tabindex="-1"><a class="header-anchor" href="#d-reviewer-agent-审阅与守门" aria-hidden="true">#</a> D. Reviewer Agent（审阅与守门）</h3><p>职责：</p><ul><li>校验链路：数据结果是否自洽、图表与数据是否匹配、单位/口径是否一致</li><li>失败时输出“可执行的修复指令”（回到 Supervisor 触发重跑某一步），而不是输出长篇解释</li></ul><p>输出（示例）：</p><div class="language-json line-numbers-mode" data-ext="json"><pre class="language-json"><code><span class="token punctuation">{</span>
  <span class="token property">&quot;status&quot;</span><span class="token operator">:</span> <span class="token string">&quot;fail&quot;</span><span class="token punctuation">,</span>
  <span class="token property">&quot;issues&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span>
    <span class="token punctuation">{</span> <span class="token property">&quot;type&quot;</span><span class="token operator">:</span> <span class="token string">&quot;chart_mismatch&quot;</span><span class="token punctuation">,</span> <span class="token property">&quot;message&quot;</span><span class="token operator">:</span> <span class="token string">&quot;line_sales 的 xAxis 使用 date，但数据表字段是 month&quot;</span><span class="token punctuation">,</span> <span class="token property">&quot;fix&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token property">&quot;rerunTaskId&quot;</span><span class="token operator">:</span> <span class="token string">&quot;t3&quot;</span> <span class="token punctuation">}</span> <span class="token punctuation">}</span>
  <span class="token punctuation">]</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="_6-1-4-状态机与共享上下文-把-agent-系统工程化的关键" tabindex="-1"><a class="header-anchor" href="#_6-1-4-状态机与共享上下文-把-agent-系统工程化的关键" aria-hidden="true">#</a> 6.1.4 状态机与共享上下文：把 Agent 系统工程化的关键</h2><p>多智能体一旦落地，就会产生两个“必答题”：</p><ol><li>共享上下文怎么设计，才能既可追踪又不爆 Token？</li><li>任务状态怎么管理，才能支持失败重试与断点续跑？</li></ol><p>推荐采用“<strong>强结构化上下文 + 弱文本上下文</strong>”组合：</p><ul><li>强结构化上下文（写入 Redis / DB）：Plan、每一步的输入输出、工具调用参数、耗时、错误</li><li>弱文本上下文（只给模型看）：每一步的摘要（Summary）+ 当前需要的局部数据片段</li></ul><h3 id="共享上下文最小数据结构" tabindex="-1"><a class="header-anchor" href="#共享上下文最小数据结构" aria-hidden="true">#</a> 共享上下文最小数据结构</h3><p>以 <code>analysisId</code> 为会话主键（可复用你现有的分析结果实体/JobId），定义一份可序列化的上下文：</p><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token keyword">type</span> <span class="token class-name">AgentRole</span> <span class="token operator">=</span> <span class="token string">&#39;router&#39;</span> <span class="token operator">|</span> <span class="token string">&#39;data_coder&#39;</span> <span class="token operator">|</span> <span class="token string">&#39;viz&#39;</span> <span class="token operator">|</span> <span class="token string">&#39;reviewer&#39;</span> <span class="token operator">|</span> <span class="token string">&#39;writer&#39;</span><span class="token punctuation">;</span>

<span class="token keyword">type</span> <span class="token class-name">TaskStatus</span> <span class="token operator">=</span> <span class="token string">&#39;pending&#39;</span> <span class="token operator">|</span> <span class="token string">&#39;running&#39;</span> <span class="token operator">|</span> <span class="token string">&#39;success&#39;</span> <span class="token operator">|</span> <span class="token string">&#39;failed&#39;</span> <span class="token operator">|</span> <span class="token string">&#39;skipped&#39;</span><span class="token punctuation">;</span>

<span class="token keyword">interface</span> <span class="token class-name">AgentTask</span> <span class="token punctuation">{</span>
  id<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">;</span>
  type<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">;</span>
  status<span class="token operator">:</span> TaskStatus<span class="token punctuation">;</span>
  inputs<span class="token operator">:</span> Record<span class="token operator">&lt;</span><span class="token builtin">string</span><span class="token punctuation">,</span> <span class="token builtin">unknown</span><span class="token operator">&gt;</span><span class="token punctuation">;</span>
  outputs<span class="token operator">?</span><span class="token operator">:</span> Record<span class="token operator">&lt;</span><span class="token builtin">string</span><span class="token punctuation">,</span> <span class="token builtin">unknown</span><span class="token operator">&gt;</span><span class="token punctuation">;</span>
  error<span class="token operator">?</span><span class="token operator">:</span> <span class="token punctuation">{</span> message<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">;</span> code<span class="token operator">?</span><span class="token operator">:</span> <span class="token builtin">string</span> <span class="token punctuation">}</span><span class="token punctuation">;</span>
  startedAt<span class="token operator">?</span><span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">;</span>
  finishedAt<span class="token operator">?</span><span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">;</span>
  tokens<span class="token operator">?</span><span class="token operator">:</span> <span class="token punctuation">{</span> input<span class="token operator">?</span><span class="token operator">:</span> <span class="token builtin">number</span><span class="token punctuation">;</span> output<span class="token operator">?</span><span class="token operator">:</span> <span class="token builtin">number</span><span class="token punctuation">;</span> total<span class="token operator">?</span><span class="token operator">:</span> <span class="token builtin">number</span> <span class="token punctuation">}</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token keyword">interface</span> <span class="token class-name">AnalysisRunContext</span> <span class="token punctuation">{</span>
  analysisId<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">;</span>
  datasetId<span class="token operator">?</span><span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">;</span>
  userPrompt<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">;</span>
  plan<span class="token operator">?</span><span class="token operator">:</span> <span class="token punctuation">{</span> goal<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">;</span> tasks<span class="token operator">:</span> AgentTask<span class="token punctuation">[</span><span class="token punctuation">]</span> <span class="token punctuation">}</span><span class="token punctuation">;</span>
  artifacts<span class="token operator">:</span> Record<span class="token operator">&lt;</span><span class="token builtin">string</span><span class="token punctuation">,</span> <span class="token builtin">unknown</span><span class="token operator">&gt;</span><span class="token punctuation">;</span>
  summaries<span class="token operator">:</span> <span class="token builtin">Array</span><span class="token operator">&lt;</span><span class="token punctuation">{</span> role<span class="token operator">:</span> AgentRole<span class="token punctuation">;</span> text<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">;</span> at<span class="token operator">:</span> <span class="token builtin">string</span> <span class="token punctuation">}</span><span class="token operator">&gt;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>其中：</p><ul><li><code>artifacts</code> 用来存放“可以复用的产物”：清洗后的表、聚合后的表、图表 option、异常列表</li><li><code>summaries</code> 用来控制 Token：每完成一个 task，就产出 3~8 行摘要供后续 Agent 使用</li></ul><h3 id="状态机-推荐" tabindex="-1"><a class="header-anchor" href="#状态机-推荐" aria-hidden="true">#</a> 状态机（推荐）</h3><p>以 Plan 为中心的状态机，比“自由对话式”更稳：</p><ol><li><code>ROUTED</code>：Router 生成 plan</li><li><code>EXECUTING</code>：Supervisor 按 tasks 执行（可并行）</li><li><code>REVIEWING</code>：Reviewer 审阅与决策（通过/重跑/降级）</li><li><code>FINALIZING</code>：Writer 汇总产出（文本 + 图表元数据）</li><li><code>DONE</code>：写入最终结果，发送完成事件</li></ol><hr><h2 id="_6-1-5-在-nestjs-bullmq-上落地-一步一步实现" tabindex="-1"><a class="header-anchor" href="#_6-1-5-在-nestjs-bullmq-上落地-一步一步实现" aria-hidden="true">#</a> 6.1.5 在 NestJS + BullMQ 上落地：一步一步实现</h2><p>这一节的“实现”指：把多 Agent 的骨架、协议与编排跑通；具体的“代码执行器/RAG/鉴权/计费”在 6.2~6.5 逐步叠加。</p><h3 id="step-1-抽象-agent-接口-让换模型-换角色变简单" tabindex="-1"><a class="header-anchor" href="#step-1-抽象-agent-接口-让换模型-换角色变简单" aria-hidden="true">#</a> Step 1：抽象 Agent 接口（让换模型/换角色变简单）</h3><p>目标：每个 Agent 都长一样，Supervisor 只需要按 role 调用。</p><p>建议接口：</p><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token keyword">interface</span> <span class="token class-name">Agent<span class="token operator">&lt;</span>Input<span class="token punctuation">,</span> Output<span class="token operator">&gt;</span></span> <span class="token punctuation">{</span>
  role<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">;</span>
  <span class="token function">run</span><span class="token punctuation">(</span>input<span class="token operator">:</span> Input<span class="token punctuation">,</span> context<span class="token operator">:</span> AnalysisRunContext<span class="token punctuation">)</span><span class="token operator">:</span> <span class="token builtin">Promise</span><span class="token operator">&lt;</span>Output<span class="token operator">&gt;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>落点：</p><ul><li>把 prompt 模板按 role 拆分（Router/Data/Viz/Reviewer），并统一走 Zod 验证</li><li>当前项目已经有 <code>zod</code> 依赖，可用于“结构化输出 + 校验 + 失败重试”</li></ul><h3 id="step-2-在-bullmq-中引入-分析编排-job" tabindex="-1"><a class="header-anchor" href="#step-2-在-bullmq-中引入-分析编排-job" aria-hidden="true">#</a> Step 2：在 BullMQ 中引入“分析编排 Job”</h3><p>目标：把“长链路、多步骤”放到 Worker 里跑，API 只负责接收请求与返回 JobId。</p><p>做法：</p><ul><li>一个 <code>analysis-orchestrator</code> 队列：负责按 plan 执行 tasks</li><li>可选拆分：<code>analysis-data-worker</code>、<code>analysis-viz-worker</code>，让不同步骤按资源隔离</li></ul><h3 id="step-3-共享上下文存储-redis-优先-db-用于审计" tabindex="-1"><a class="header-anchor" href="#step-3-共享上下文存储-redis-优先-db-用于审计" aria-hidden="true">#</a> Step 3：共享上下文存储（Redis 优先，DB 用于审计）</h3><p>建议策略：</p><ul><li>Redis 存 <code>AnalysisRunContext</code>（短 TTL，例如 24 小时，用于实时进度与断点）</li><li>DB 存 <code>AnalysisRun</code> / <code>AgentStep</code>（长期保存，用于回放、审计、计费、复盘）</li></ul><p>你当前项目已集成 Redis（用于 BullMQ 与 CacheManager），可以复用。</p><h3 id="step-4-实时进度推送-websocket-给状态-sse-给文本" tabindex="-1"><a class="header-anchor" href="#step-4-实时进度推送-websocket-给状态-sse-给文本" aria-hidden="true">#</a> Step 4：实时进度推送（WebSocket 给状态，SSE 给文本）</h3><p>建议分工：</p><ul><li>WebSocket：推结构化的 step 更新（task status、artifacts keys、错误）</li><li>SSE：推“可读文本流”（例如 Writer 的报告逐字输出，或 Supervisor 的进度日志）</li></ul><p>当你把每一步结构化记录下来后，前端就可以做出“任务看板式”的可视化，而不只是输出一段文字。</p><h3 id="step-5-失败语义与重试策略-工程化的稳定性来源" tabindex="-1"><a class="header-anchor" href="#step-5-失败语义与重试策略-工程化的稳定性来源" aria-hidden="true">#</a> Step 5：失败语义与重试策略（工程化的稳定性来源）</h3><p>分层重试：</p><ul><li>LLM 输出不符合 schema：同一步内部重试（最多 N 次）</li><li>计算/工具执行失败：重跑该 task（最多 N 次），必要时降级策略（例如跳过某个图表）</li><li>Reviewer 判定失败：只重跑相关 task（按 <code>rerunTaskId</code>），不从头开始</li></ul><p>必须设置：</p><ul><li><code>maxSteps</code>：防止死循环</li><li><code>maxTokensBudget</code>：防止无限烧钱</li><li><code>timeoutMs</code>：防止任务永久挂起</li></ul><hr><h2 id="_6-1-6-验收标准-做到这些就算-多智能体骨架跑通" tabindex="-1"><a class="header-anchor" href="#_6-1-6-验收标准-做到这些就算-多智能体骨架跑通" aria-hidden="true">#</a> 6.1.6 验收标准（做到这些就算“多智能体骨架跑通”）</h2><p>当你完成本节改造后，应能满足以下验收点：</p><ul><li>能生成结构化 Plan，并按 Plan 执行至少 3 类 Worker（计算、图表、审阅）</li><li>任何一步失败都能定位到 task，并能针对性重跑</li><li>每一步都有可回放记录（至少 Redis，最好 DB 也有审计）</li><li>前端能实时看到每一步状态变化（running/success/failed）与主要产物 key</li></ul><p>做到这里，你的项目就从“会跑的 Demo”迈入“可持续演进的工程系统”，后续 6.2~6.5 的能力才能稳定叠加上去。</p>`,81)])])}const c=n(e,[["render",o],["__file","6.1 从单体 Agent 到多智能体架构.html.vue"]]);export{c as default};
